from auto_config.generator.enb.managed_objects.managed_object import ManagedObject


class FeatcadmParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        smod_prod_code = None
        if 'smods' in self.enb_ent_config:
            smod_prod_code = self.enb_ent_config['smods']['1'].get('prod_code_planned')
        self.set_actDualStackIpV4V6ForMplane()
        if self.is_rf_chain():
            self.set_parameter('actRfChaining', 'true')
        if smod_prod_code in ["476255A", "476254A", "476147A"] and execution_config['release'] >= 25.1:  # ASOH/G/F
            self.set_parameter('cntrldResetMplaneBreakTime', '220')
        if execution_config['release'] >= 25.22502:
            self.set_parameter('cntrldResetMplaneBreakTime', '420')
            self.set_parameter('uncntrldResetMplaneBreakTime', '0')
        elif execution_config['release'] >= 25.1:
            self.set_parameter('cntrldResetMplaneBreakTime', '220')
            self.set_parameter('uncntrldResetMplaneBreakTime', '0')

    def set_actDualStackIpV4V6ForMplane(self):
        if self.enb_ent_config['is_ipv6_mplane']:
            actDualStackIpV4V6ForMplane = 'true'
        else:
            actDualStackIpV4V6ForMplane = 'false'
        self.set_parameter('actDualStackIpV4V6ForMplane', actDualStackIpV4V6ForMplane)

    def is_rf_chain(self):
        return any('rmod' in radio for radio in self.enb_ent_config['radios'].values())
